// Mapa: odlomak (w:p cvor) -> pozicija u tablici {tableId,row,col} za faksimil grupiranje u <table>.
// Direktna djeca (ne descendants) po razini, pa ugnjezdena tablica dobiva svoj tableId, a odlomci
// vanjske celije ne skupljaju ugnjezdene retke. Bez tablica vraca praznu mapu (cell ostaje undefined).
function childrenByTag(node: any,tag: string): any[]{
  const out: any[]=[];const kids=node&&node.childNodes?node.childNodes:[];
  for(let i=0;i<kids.length;i++){const k=kids[i];if(k&&(k.nodeName===tag||k.localName===tag.split(':').pop()))out.push(k);}
  return out;
}
function buildTableCellMap(doc: any): Map<any,any>{
  const map=new Map();const tbls=els(doc,'w:tbl');
  tbls.forEach((tbl: any,ti: number)=>{
    childrenByTag(tbl,'w:tr').forEach((tr: any,ri: number)=>{
      childrenByTag(tr,'w:tc').forEach((tc: any,ci: number)=>{
        for(const p of childrenByTag(tc,'w:p'))map.set(p,{tableId:ti,row:ri,col:ci});
      });
    });
  });
  return map;
}

