// Bajtove razrjesava resolvePreviewImages u fazi sastavljanja pregleda (gdje su relMap i zip dostupni),
// pa se citaju samo slike odlomaka koji stvarno udju u pregled. Slika ostaje LOKALNA (data: URI,
// nikad na mrezu; sanitizeAnalysisResult izbacuje cijeli `preview`).
const PREVIEW_IMG_MIME: Record<string,string>={png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',gif:'image/gif',bmp:'image/bmp',webp:'image/webp'};
