function collectImageRefs(p: any): any[]{
  const out: any[]=[];
  for(const d of els(p,'w:drawing')){
    const blip=first(d,'a:blip'),relId=blip?attr(blip,'r:embed'):null;
    if(!relId)continue;
    const ext=first(d,'wp:extent'),cx=ext?Number(attr(ext,'cx')):NaN,cy=ext?Number(attr(ext,'cy')):NaN;
    out.push({relId,wEmu:Number.isFinite(cx)&&cx>0?cx:null,hEmu:Number.isFinite(cy)&&cy>0?cy:null});
  }
  for(const pict of els(p,'w:pict')){
    const im=first(pict,'v:imagedata'),relId=im?attr(im,'r:id'):null;
    if(relId)out.push({relId,wEmu:null,hEmu:null});
  }
  return out;
}

function imagePixelDimensions(bytes: Uint8Array): { widthPx: number; heightPx: number } | null {
  if (bytes.length >= 24 && bytes[0] === 0x89 && bytes[1] === 0x50 && bytes[2] === 0x4e && bytes[3] === 0x47) {
    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    return { widthPx: view.getUint32(16), heightPx: view.getUint32(20) };
  }
  if (bytes.length > 10 && bytes[0] === 0xff && bytes[1] === 0xd8) {
    for (let i = 2; i + 9 < bytes.length;) {
      if (bytes[i] !== 0xff) { i += 1; continue; }
      const marker = bytes[i + 1];
      const length = (bytes[i + 2] << 8) | bytes[i + 3];
      if (length < 2 || i + length + 2 > bytes.length) break;
      if ((marker >= 0xc0 && marker <= 0xc3) || (marker >= 0xc5 && marker <= 0xc7) || (marker >= 0xc9 && marker <= 0xcb) || (marker >= 0xcd && marker <= 0xcf)) {
        return { heightPx: (bytes[i + 5] << 8) | bytes[i + 6], widthPx: (bytes[i + 7] << 8) | bytes[i + 8] };
      }
      i += length + 2;
    }
  }
  return null;
}

async function rescueMediaInfo(document: Document, relMap: Map<string, string>, zip: any): Promise<Record<string, { widthPx?: number; heightPx?: number; mime?: string }>> {
  const result: Record<string, { widthPx?: number; heightPx?: number; mime?: string }> = {};
  const ids = new Set<string>();
  for (const node of els(document, '*')) {
    const id = attr(node, 'r:embed') || attr(node, 'r:id');
    if (id) ids.add(id);
  }
  for (const id of ids) {
    const target = relMap.get(id);
    if (!target) continue;
    let path = String(target).replace(/^\//, '').replace(/^\.\.\//, '');
    if (!path.startsWith('word/')) path = `word/${path}`;
    try {
      const bytes = await zip.data(path);
      const dimensions = imagePixelDimensions(bytes);
      if (dimensions) result[id] = dimensions;
    } catch { /* nedostupna slika ostaje bez DPI procjene */ }
  }
  return result;
}

function u8ToBase64(bytes: Uint8Array): string{
  let bin='';
  for(let i=0;i<bytes.length;i++)bin+=String.fromCharCode(bytes[i]);
  return btoa(bin);
}

