/**
 * Je li `w:sectPr` ZIVA postavka sekcije, a ne povijesna kopija unutar `w:sectPrChange`?
 *
 * `els()` je getElementsByTagName (svi potomci), pa praceni dokument (Track Changes nad
 * postavkama stranice) daje ugnjezdeni `<w:sectPr>` unutar `<w:sectPrChange>`. Bez ovog
 * filtera takva kopija ulazi u `details.sections` kao stvarna sekcija, sto kvari i BODOVANE
 * provjere koje broje sekcije (margine, format stranice, numeriranje) i gasi ponudu popravka
 * koja gejta na `sections.length === 1`.
 */
function isLiveSectPr(node: any): boolean {
  for (let p = node?.parentNode; p; p = p.parentNode) {
    const name = p.localName || p.nodeName;
    if (name === 'sectPrChange' || name === 'w:sectPrChange') return false;
    if (name === 'body' || name === 'w:body') break;
  }
  return true;
}

// BACKLOG (faza D, sav 2+): ovaj omotac PONOVNO otvara zip i gradi requiredSections/linkDoi
// strukture nad preview.paragraphs; kandidat za spajanje u analyzeDocxInternal NAKON sto se
// sav 2 (structure evaluacije) slegne. Ne dirati usput: nije u goldenu, ali jest UI ugovor.
export async function analyzeDocx(file: File, profile: any, settings: any, onProgress: any, options?: AnalyzeDocxOptions) {
  const result: any = await analyzeDocxInternal(file, profile, settings, onProgress, options);
  try {
    const zip = new ZipReader(await file.arrayBuffer(), settings?.maxDecompressedBytes ? { maxDecompressedBytes: settings.maxDecompressedBytes } : {});
    const documentXml = await zip.text('word/document.xml');
    const documentRelsXml = await zip.text('word/_rels/document.xml.rels');
    result.details.requiredSectionsStructure = analyzeRequiredSectionsStructure({
      documentXml,
      paragraphs: Array.isArray(result.preview?.paragraphs) ? result.preview.paragraphs.map((p: any) => ({ index: Number(p.index), text: String(p.text || ''), headingLevel: p.headingLevel || null })) : [],
      profileRequiredSections: profile.effectiveRules?.requiredSections || profile.requiredSections,
      rules: profile.effectiveRules?.requiredSectionRules || profile.requiredSectionRules,
    });
    result.details.linkDoiStructure = analyzeLinkDoiStructure({
      documentXml,
      documentRelsXml,
      paragraphs: Array.isArray(result.preview?.paragraphs) ? result.preview.paragraphs.map((p: any) => ({ index: Number(p.index), text: String(p.text || '') })) : [],
      rules: profile.effectiveRules?.linkRules || profile.linkRules,
    });
  } catch {
    result.details.requiredSectionsStructure = { version: 1, candidates: [], warnings: ['Nije bilo moguće ponovno analizirati strukturu obveznih dijelova.'], skipped: [], summary: { required: 0, present: 0, missing: 0, high: 0, medium: 0, low: 0, text: 'Analiza nije dostupna.' } };
    result.details.linkDoiStructure = { version: 1, occurrences: [], warnings: ['Nije bilo moguće analizirati poveznice.'], skipped: [], summary: { total: 0, plainUrls: 0, doiCandidates: 0, brokenUrls: 0, trackingUrls: 0, mismatches: 0, redirects: 0, unreachable: 0 } };
  }
  return result;
}
